using ERPWMS.Database.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System;using System.Linq;using System.Security.Claims;using System.Threading.Tasks;
using ERPWMS.Database;
namespace ERPWMS.Controllers.Workflow{[Authorize]public class WorkflowDefinitionController:Controller{private readonly AppDbContext _context;public WorkflowDefinitionController(AppDbContext c){_context=c;}
private int Uid(){var cl=User.FindFirstValue(ClaimTypes.NameIdentifier);if(int.TryParse(cl,out var i)&&i>0)return i;var u=_context.Users.FirstOrDefault();return u!=null?u.Id:1;}
[HttpGet]public IActionResult Index()=>View();
[HttpGet]public async Task<IActionResult> GetStatistics(){var l=await _context.WorkflowDefinitions.Where(d=>d.IsDeleted!=true).ToListAsync();return Json(new{total=l.Count,active=l.Count(d=>d.IsActive == true),inactive=l.Count(d=>d.IsActive!=true),addedThisMonth=l.Count(d=>d.CreatedDate.HasValue&&d.CreatedDate.Value.Month==DateTime.Now.Month&&d.CreatedDate.Value.Year==DateTime.Now.Year)});}
[HttpGet]public async Task<IActionResult> GetAll(){var l=await _context.WorkflowDefinitions.Where(d=>d.IsDeleted!=true).OrderBy(d => d.WorkflowDefId).Select(d=>new{workflowDefId=d.WorkflowDefId,workflowName=d.WorkflowName,moduleType=d.ModuleType,description=d.Description??"",stageCount=_context.WorkflowStages.Count(s=>s.WorkflowDefId==d.WorkflowDefId&&s.IsDeleted!=true),isActive=d.IsActive??false,createdDate=d.CreatedDate}).ToListAsync();return Json(l);}
[HttpGet]public IActionResult AddPartial()=>PartialView("_AddForm");
[HttpGet]public async Task<IActionResult> EditPartial(int id){var d=await _context.WorkflowDefinitions.FindAsync(id);if(d==null)return NotFound();return PartialView("_EditForm",d);}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Register(string workflowName,string moduleType,string description){try{if(string.IsNullOrWhiteSpace(workflowName))return Json(new{success=false,message="Workflow name required."});_context.WorkflowDefinitions.Add(new WorkflowDefinition{WorkflowName=workflowName.Trim(),ModuleType=moduleType??"General",Description=description??"",IsActive=true,IsDeleted=false,CreatedBy=Uid().ToString(),CreatedDate=DateTime.Now});await _context.SaveChangesAsync();return Json(new{success=true,message="Workflow registered!"});}catch(Exception ex){return Json(new{success=false,message=(ex.InnerException??ex).Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Edit(int workflowDefId,string workflowName,string moduleType,string description,bool isActive=true){try{var d=await _context.WorkflowDefinitions.FindAsync(workflowDefId);if(d==null)return Json(new{success=false,message="Not found"});d.WorkflowName=workflowName.Trim();d.ModuleType=moduleType??"General";d.Description=description??"";d.IsActive=isActive;d.UpdatedBy=Uid().ToString();d.UpdatedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message="Workflow updated!"});}catch(Exception ex){return Json(new{success=false,message=(ex.InnerException??ex).Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Delete(int id){try{var d=await _context.WorkflowDefinitions.FindAsync(id);if(d==null)return Json(new{success=false});d.IsDeleted=true;d.IsActive=false;d.DeletedBy=Uid().ToString();d.DeletedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message="Deleted."});}catch(Exception ex){return Json(new{success=false,message=ex.Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Toggle(int id){try{var d=await _context.WorkflowDefinitions.FindAsync(id);if(d==null)return Json(new{success=false});d.IsActive=!(d.IsActive??false);d.UpdatedBy=Uid().ToString();d.UpdatedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message=d.IsActive == true?"Activated.":"Deactivated."});}catch(Exception ex){return Json(new{success=false,message=ex.Message});}}
[HttpGet]public async Task<IActionResult> Profile(int id){var d=await _context.WorkflowDefinitions.FindAsync(id);if(d==null)return NotFound();ViewBag.StageCount=await _context.WorkflowStages.CountAsync(s=>s.WorkflowDefId==id&&s.IsDeleted!=true);ViewBag.InstanceCount=await _context.WorkflowInstances.CountAsync(i=>i.WorkflowDefId==id);return View(d);}
}}
